int main(void)
{
	for (size_t i = 0; i < sizeof t / sizeof *t; i++) {
		double d = strtod(t[i].s, 0);
		if (d != t[i].want) {
			CHECK(d == t[i].want);
			write(2, t[i].s, 20);
			write(2, "\n", 1);
		}
	}
	CHECK(strtod("0x1p4", 0) == 16.0);
	CHECK(strtod("0x1.1p4", 0) == 17.0);
	return t_status;
}
